fn solve(m: i8, d: i8) -> i8 {
    // Determine days in the month (non-leap year)
    let days_in_month: i8 = match m {
        1 => 31,  // January
        2 => 28,  // February (non-leap)
        3 => 31,  // March
        4 => 30,  // April
        5 => 31,  // May
        6 => 30,  // June
        7 => 31,  // July
        8 => 31,  // August
        9 => 30,  // September
        10 => 31, // October
        11 => 30, // November
        12 => 31, // December
        _ => 0,   // Invalid month (won't happen per problem constraints)
    };

    // Calculate total cells needed: (d - 1) empty days + days_in_month
    let total_cells = (d - 1) + days_in_month;
    
    // Calculate number of weeks: ceil(total_cells / 7)
    // This is equivalent to: (total_cells + 6) / 7
    let weeks = (total_cells + 6) / 7;
    
    weeks
}